definition:
faith_creation.1021 = {
	type = character_event
	title = {
		first_valid = {
			triggered_desc = {
				trigger = { this = scope:founder }
				desc = faith_creation.1021.t.founder
			}
			desc = faith_creation.1021.t
		}
	}
	desc = {
		# Who founded it, and from which side it is seen.
		first_valid = {
			triggered_desc = {
				trigger = { this = scope:founder }
				desc = faith_creation.1021.desc.intro.founder
			}
			desc = faith_creation.1021.desc.intro.observer
		}
		# How far it stands from the rite it branched off from.
		first_valid = {
			triggered_desc = {
				trigger = { "scope:new_rite.divergence(scope:source_rite)" < minor_rite_divergence_value }
				desc = faith_creation.1021.desc.divergence.minor
			}
			triggered_desc = {
				trigger = { "scope:new_rite.divergence(scope:source_rite)" >= medium_rite_divergence_value }
				desc = faith_creation.1021.desc.divergence.major
			}
			desc = faith_creation.1021.desc.divergence.moderate
		}
		first_valid = {
			triggered_desc = {
				trigger = { exists = scope:differing_tenet }
				desc = faith_creation.1021.desc.differing.tenet
			}
			triggered_desc = {
				trigger = { exists = scope:differing_doctrine }
				desc = faith_creation.1021.desc.differing.doctrine
			}
			desc = faith_creation.1021.desc.differing.fallback
		}
		first_valid = {
			triggered_desc = {
				trigger = {
					this = scope:founder
					scope:source_rite = scope:old_faith.main_rite
				}
				desc = faith_creation.1021.desc.outro.founder.mainline
			}
			triggered_desc = {
				trigger = { this = scope:founder }
				desc = faith_creation.1021.desc.outro.founder.branch
			}
			desc = faith_creation.1021.desc.outro.observer
		}
	}

	theme = faith

	widget = {
		gui = "event_window_widget_rite_founder"
		container = "custom_widgets_container"
	}

	left_portrait = {
		character = scope:founder
		animation = preaching
		camera = camera_event_right_forward
	}

	trigger = {
		exists = scope:founder
		exists = scope:new_rite
		exists = scope:source_rite
		exists = scope:old_faith
	}

	immediate = {
		play_music_cue = "mx_cue_sacredrite"
	}

	option = {
		name = faith_creation.1021.a.founder
		trigger = { this = scope:founder }
		change_spiritual_fulfillment = medium_spiritual_fulfillment_value
		add_piety = minor_piety_gain
	}

	option = {
		name = faith_creation.1021.b.founder
		trigger = { this = scope:founder }
		add_prestige = medium_prestige_gain
		add_piety = minor_piety_loss
	}

	# For multiplayer onlookers only, since conversion already went out and effects stay on the chooser
	option = {
		name = faith_creation.1021.a
		trigger = { NOT = { this = scope:founder } }
		change_spiritual_fulfillment = medium_spiritual_fulfillment_value
	}

	option = {
		name = faith_creation.1021.b
		trigger = { NOT = { this = scope:founder } }
		add_piety = minor_piety_gain
	}
}
